package com.secure.documentwallet;

import android.content.*;import android.graphics.*;import android.graphics.pdf.PdfRenderer;import android.net.Uri;import android.os.ParcelFileDescriptor;import android.provider.OpenableColumns;import android.text.Html;import java.io.*;import java.util.*;import java.util.zip.*;

/** Converts supported uploads into private image pages that the existing encrypted vault can preview. */
final class DocumentImporter {
 private static final int PAGE_W=1600,PAGE_H=2200,MAX_PAGES=40;private final Context context;private final File cache;
 DocumentImporter(Context context){this.context=context.getApplicationContext();cache=new File(context.getCacheDir(),"imported_pages");if(!cache.exists())cache.mkdirs();}
 ArrayList<Uri> convert(Uri source,String kind)throws Exception{if("pdf".equals(kind))return pdf(source);if("word".equals(kind))return docx(source);return image(source);}
 String displayName(Uri uri){String value=null;try(android.database.Cursor cursor=context.getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())value=cursor.getString(0);}catch(Exception ignored){}if(value==null||value.trim().isEmpty())value="Uploaded Item";int dot=value.lastIndexOf('.');return dot>0?value.substring(0,dot):value;}
 private ArrayList<Uri> image(Uri source)throws Exception{Bitmap bitmap=decode(source,2800);if(bitmap==null)throw new IOException("This Image Could Not Be Read");ArrayList<Uri> out=new ArrayList<>();out.add(write(bitmap,0));bitmap.recycle();return out;}
 private ArrayList<Uri> pdf(Uri source)throws Exception{ArrayList<Uri> out=new ArrayList<>();try(ParcelFileDescriptor descriptor=context.getContentResolver().openFileDescriptor(source,"r")){if(descriptor==null)throw new IOException("This PDF Could Not Be Opened");try(PdfRenderer renderer=new PdfRenderer(descriptor)){if(renderer.getPageCount()==0)throw new IOException("This PDF Has No Pages");int total=Math.min(renderer.getPageCount(),MAX_PAGES);for(int i=0;i<total;i++){try(PdfRenderer.Page page=renderer.openPage(i)){float scale=Math.min(1800f/page.getWidth(),2400f/page.getHeight());int width=Math.max(1,Math.round(page.getWidth()*scale)),height=Math.max(1,Math.round(page.getHeight()*scale));Bitmap bitmap=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);canvas.drawColor(Color.WHITE);page.render(bitmap,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);out.add(write(bitmap,i));bitmap.recycle();}}}}if(out.isEmpty())throw new IOException("No PDF Preview Could Be Created");return out;}
 private ArrayList<Uri> docx(Uri source)throws Exception{String xml=null;ArrayList<byte[]> media=new ArrayList<>();InputStream raw=context.getContentResolver().openInputStream(source);if(raw==null)throw new IOException("This Word Document Could Not Be Opened");try(InputStream input=raw;ZipInputStream zip=new ZipInputStream(new BufferedInputStream(input))){for(ZipEntry entry;(entry=zip.getNextEntry())!=null;){if(entry.isDirectory())continue;String name=entry.getName();if("word/document.xml".equals(name)||name.startsWith("word/media/")){ByteArrayOutputStream bytes=new ByteArrayOutputStream();copy(zip,bytes);if("word/document.xml".equals(name))xml=bytes.toString("UTF-8");else media.add(bytes.toByteArray());}}}catch(ZipException error){throw new IOException("Please Choose A Modern Word .docx File");}if(xml==null)throw new IOException("This Word Document Could Not Be Read");String text=extractWordText(xml).trim();ArrayList<Uri> pages=text.isEmpty()?new ArrayList<>():renderText(text);int page=pages.size();for(byte[] bytes:media){if(page>=MAX_PAGES)break;Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length);if(bitmap!=null){pages.add(write(bitmap,page++));bitmap.recycle();}}if(pages.isEmpty())throw new IOException("No Readable Text Or Images Were Found In This Word Document");return pages;}
 private String extractWordText(String xml){String withBreaks=xml.replaceAll("(?i)</w:p\\s*>","\n").replaceAll("(?i)<w:tab[^>]*/>","    ").replaceAll("(?i)<w:br[^>]*/>","\n");String plain=withBreaks.replaceAll("<[^>]+>","");return Html.fromHtml(plain,Html.FROM_HTML_MODE_LEGACY).toString();}
 private ArrayList<Uri> renderText(String content)throws Exception{ArrayList<String> lines=wrap(content);ArrayList<Uri> pages=new ArrayList<>();Paint body=new Paint(Paint.ANTI_ALIAS_FLAG);body.setColor(0xff152a35);body.setTextSize(42);body.setTypeface(Typeface.create(Typeface.SANS_SERIF,Typeface.NORMAL));Paint header=new Paint(Paint.ANTI_ALIAS_FLAG);header.setColor(0xff0b8179);header.setTextSize(52);header.setTypeface(Typeface.create(Typeface.SANS_SERIF,Typeface.BOLD));int perPage=42,cursor=0,pageNumber=0;while(cursor<lines.size()&&pageNumber<MAX_PAGES){Bitmap bitmap=Bitmap.createBitmap(PAGE_W,PAGE_H,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);canvas.drawColor(0xfffdfcf8);canvas.drawText("Imported Word Document",110,125,header);Paint rule=new Paint(Paint.ANTI_ALIAS_FLAG);rule.setColor(0xffd6ad52);rule.setStrokeWidth(4);canvas.drawLine(110,155,PAGE_W-110,155,rule);float y=230;for(int row=0;row<perPage&&cursor<lines.size();row++,cursor++){canvas.drawText(lines.get(cursor),110,y,body);y+=45;}pages.add(write(bitmap,pageNumber));bitmap.recycle();pageNumber++;}return pages;}
 private ArrayList<String> wrap(String content){Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);paint.setTextSize(42);ArrayList<String> out=new ArrayList<>();for(String paragraph:content.replace("\r","").split("\n",-1)){String remaining=paragraph.trim();if(remaining.isEmpty()){out.add("");continue;}while(!remaining.isEmpty()){int count=paint.breakText(remaining,true,PAGE_W-220,null);if(count<=0)break;if(count<remaining.length()){int space=remaining.lastIndexOf(' ',count);if(space>0)count=space;}out.add(remaining.substring(0,count).trim());remaining=remaining.substring(count).trim();}}return out;}
 private Bitmap decode(Uri uri,int max)throws Exception{BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;try(InputStream input=context.getContentResolver().openInputStream(uri)){BitmapFactory.decodeStream(input,null,bounds);}int sample=1;while(Math.max(bounds.outWidth,bounds.outHeight)/sample>max)sample*=2;BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=sample;try(InputStream input=context.getContentResolver().openInputStream(uri)){return BitmapFactory.decodeStream(input,null,options);}}
 private Uri write(Bitmap bitmap,int index)throws Exception{File file=new File(cache,"import-"+System.nanoTime()+"-"+index+".jpg");try(OutputStream output=new BufferedOutputStream(new FileOutputStream(file))){bitmap.compress(Bitmap.CompressFormat.JPEG,94,output);}return Uri.fromFile(file);}
 static void cleanup(List<Uri> pages){for(Uri uri:pages)if("file".equals(uri.getScheme())){File file=new File(uri.getPath());if(file.getName().startsWith("import-"))file.delete();}}
 private static void copy(InputStream input,OutputStream output)throws IOException{byte[] buffer=new byte[32768];for(int read;(read=input.read(buffer))!=-1;)output.write(buffer,0,read);}
}
